/*
 * Serialises a sidebar layout model into the contents of
 * js/sidebar-layout.js — the file index.html actually loads.
 */
window.SASidebarLayoutSerialize = (function () {
  'use strict';

  var HEADER = [
    '/*',
    ' * Sidebar layout for the South Africa Dashboard.',
    ' *',
    ' * Generated by pages/sidebar-sections.html. The Save to dashboard button',
    ' * writes this file through /api/sidebar-layout — hand edits are overwritten.',
    ' *',
    ' * Set the value below to null to fall back to the sidebar markup written',
    ' * directly into index.html.',
    ' */',
    ''
  ].join('\n');

  function withoutIds(model) {
    var copy = JSON.parse(JSON.stringify(model));
    (function strip(items) {
      (items || []).forEach(function (item) {
        delete item.id;
        delete item.wrapper;
        if (item.children) strip(item.children);
      });
    })(copy.sections);
    copy.version = 1;
    return copy;
  }

  function toFileText(model) {
    return HEADER + 'window.SA_SIDEBAR_LAYOUT = ' +
      JSON.stringify(withoutIds(model), null, 2) + ';\n';
  }

  function disabledText() {
    return HEADER + 'window.SA_SIDEBAR_LAYOUT = null;\n';
  }

  function parseLayoutScript(text) {
    var marker = 'window.SA_SIDEBAR_LAYOUT = ';
    var i = String(text || '').indexOf(marker);
    if (i < 0) return null;
    var raw = text.slice(i + marker.length).trim();
    if (raw.charAt(raw.length - 1) === ';') raw = raw.slice(0, -1).trim();
    if (!raw || raw === 'null') return null;
    return JSON.parse(raw);
  }

  return {
    toFileText: toFileText,
    disabledText: disabledText,
    withoutIds: withoutIds,
    parseLayoutScript: parseLayoutScript
  };
})();
